test("85 cancelled in-flight transfer keeps busy guard until driver settles",async()=>{let finish;const d=transportDriver({transferChunk:()=>new Promise(resolve=>{finish=resolve;})}),t=createPrintTransport(d,{timeoutMs:100});const sending=t.send(new Uint8Array([1]));await tick();t.cancel();await assert.rejects(sending,e=>e.code===TRANSPORT_ERRORS.TRANSFER_CANCELLED);assert.equal(t.isBusy(),true);await assert.rejects(t.send(new Uint8Array([2])),e=>e.code===TRANSPORT_ERRORS.TRANSPORT_BUSY);finish({ok:true,bytesTransferred:1});await t.flush();assert.equal(t.isBusy(),false);});
