test("87 driver contract converts native USBOutTransferResult",async()=>{const native={status:"ok",bytesWritten:3};const d=device({transferOut:async()=>native}),p=createUsbPrinterProvider({environment:{usb:usb({requestDevice:async()=>d})}});await p.requestDevice();await p.connect();const result=await p.transferChunk(new Uint8Array([1,2,3]));assert.deepEqual(result,{ok:true,bytesTransferred:3});assert.notEqual(result,native);assert.equal("bytesWritten" in result,false);assert.equal("status" in result,false);});
test("88 transport consumes only driver result contract",async()=>{const d=transportDriver({transferChunk:async chunk=>({ok:true,bytesTransferred:chunk.byteLength,status:"native-stall",bytesWritten:999})}),t=createPrintTransport(d,{chunkSize:2});const result=await t.send(new Uint8Array([1,2,3]));assert.deepEqual(result,{bytesTransferred:3,chunksTransferred:2});});
