test("141 pipeline sequence is decision layout formatter transport",async()=>{const order=[];const deps=pipelineDependencies({decision:{async decide(){order.push("decision");return createPrintDecision({action:"print",tickets:[{layoutVariant:"customer"}]});}},layoutBuilders:{customer:()=>{order.push("layout");return createLayout("customer",[]);}},formatter:()=>{order.push("formatter");return new Uint8Array([1]);},transport:{async send(){order.push("transport");return{bytesTransferred:1};}}});const result=await createPrintPipeline(deps).execute({});assert.equal(result.success,true);assert.deepEqual(order,["decision","layout","formatter","transport"]);});
