test("168 queue processes jobs FIFO",async()=>{const order=[];const pipeline=queuePipeline({async execute(request){order.push(request.metadata.position);await tick();return createPrintResult({success:true});}}),queue=createCommercialPrintQueue({pipeline,idFactory:(()=>{let n=0;return()=>String(++n);})()});const handles=[1,2,3].map(position=>queue.enqueue(createPrintRequest({metadata:{position}})));await Promise.all(handles.map(handle=>handle.completion));assert.deepEqual(order,[1,2,3]);});
test("169 queue uses a single worker",async()=>{let active=0,max=0;const pipeline=queuePipeline({async execute(){active++;max=Math.max(max,active);await tick();active--;return createPrintResult({success:true});}}),queue=createCommercialPrintQueue({pipeline});const handles=[queue.enqueue(createPrintRequest({})),queue.enqueue(createPrintRequest({})),queue.enqueue(createPrintRequest({}))];await Promise.all(handles.map(item=>item.completion));assert.equal(max,1);});
test("170 sequential queue jobs all complete",async()=>{const queue=createCommercialPrintQueue({pipeline:queuePipeline()});const handles=Array.from({length:4},()=>queue.enqueue(createPrintRequest({})));const jobs=await Promise.all(handles.map(item=>item.completion));assert.deepEqual(jobs.map(job=>job.status),["Completed","Completed","Completed","Completed"]);});
test("171 queue emits lifecycle events",async()=>{const pipeline=queuePipeline({async execute(request,context,observer){observer.onFormatting(context);observer.onSending(context);return createPrintResult({success:true});}}),queue=createCommercialPrintQueue({pipeline});const names=[];for(const name of [QUEUE_EVENTS.JOB_QUEUED,QUEUE_EVENTS.JOB_STARTED,QUEUE_EVENTS.JOB_COMPLETED])queue.on(name,()=>names.push(name));const handle=queue.enqueue(createPrintRequest({}));await handle.completion;assert.deepEqual(names,["JobQueued","JobStarted","JobCompleted"]);});
