test("180 pipeline context reaches decision layout formatter transport",async()=>{const seen=[];const deps=pipelineDependencies({decision:{async decide(request,context){seen.push(context);return createPrintDecision({action:"print",tickets:[{layoutVariant:"customer"}]});}},layoutBuilders:{customer:(order,request,ticket,context)=>{seen.push(context);return createLayout("customer",[]);}},formatter:(layout,options)=>{seen.push(options.context);return new Uint8Array([1]);},transport:{async send(bytes,context){seen.push(context);return{bytesTransferred:1};}}}),pipeline=createPrintPipeline(deps),context=createPipelineContext({jobId:"j"});await pipeline.execute({},context);assert.equal(seen.length,4);assert.equal(seen.every(value=>value===context),true);});
