test("222 trigger validation errors cannot escape the engine",async()=>{const engine=createAutoPrintEngine({policies:createPolicyRegistry(),capabilities:createCapabilityRegistry({default:{}}),queue:{enqueue(){}}}),result=await engine.handle({type:"bad"});assert.equal(result.failed,true);assert.equal(result.errors[0].code,"AUTO_PRINT_FAILED");});
test("223 queue errors cannot escape the engine",async()=>{const engine=createAutoPrintEngine({policies:createPolicyRegistry({default:createPrintPolicy(()=>({tickets:[{}]}))}),capabilities:createCapabilityRegistry({default:{}}),queue:{enqueue(){throw Object.assign(new Error("closed"),{code:"QUEUE_CLOSED"});}}}),result=await engine.handle({type:PRINT_TRIGGER_TYPES.MANUAL_PRINT});assert.equal(result.errors[0].code,"QUEUE_CLOSED");assert.equal(result.accepted,false);});
test("224 auto print engine close is idempotent",()=>{const engine=createAutoPrintEngine({policies:createPolicyRegistry(),capabilities:createCapabilityRegistry({default:{}}),queue:{enqueue(){}}});assert.equal(engine.close(),true);assert.equal(engine.close(),false);});
test("225 closed engine returns controlled result and modules avoid forbidden dependencies",async()=>{const engine=createAutoPrintEngine({policies:createPolicyRegistry(),capabilities:createCapabilityRegistry({default:{}}),queue:{enqueue(){}}});engine.close();const result=await engine.handle({type:PRINT_TRIGGER_TYPES.TEST_PRINT});assert.equal(result.errors[0].code,"AUTO_PRINT_CLOSED");for(const name of ["auto-print-engine.js","print-trigger.js","print-policy.js","printer-capability.js","print-plan.js"]){const source=await fs.readFile(path.join(__dirname,"..","public","js",name),"utf8");for(const forbidden of ["escpos-formatter","print-transport","usb-printer-provider","printer-center","firebase","navigator.usb","document.","localStorage"])assert.equal(source.includes(forbidden),false);}});
